CREATE TABLE users (id BIGINT PRIMARY KEY, `group` TEXT);
CREATE TABLE tokens (id BIGINT PRIMARY KEY, user_id BIGINT);
CREATE TABLE channels (id BIGINT PRIMARY KEY, status INTEGER, `group` TEXT, models TEXT, restrict_models BOOLEAN, priority BIGINT, weight BIGINT);
CREATE TABLE subscription_accounts (id BIGINT PRIMARY KEY, status INTEGER, `group` TEXT, models TEXT, platform TEXT, priority BIGINT, weight BIGINT);
CREATE TABLE abilities (`group` TEXT, model TEXT, channel_id BIGINT, enabled BOOLEAN, priority BIGINT);
CREATE TABLE subscription_account_abilities (id BIGINT PRIMARY KEY, `group` TEXT, model TEXT, account_id BIGINT, platform TEXT, enabled BOOLEAN, priority BIGINT);
CREATE TABLE models (id BIGINT PRIMARY KEY, model_id TEXT, status INTEGER, is_public BOOLEAN);
CREATE TABLE model_channel_mapping (id BIGINT PRIMARY KEY, model_id BIGINT, channel_id BIGINT, enabled BOOLEAN, upstream_model_id TEXT, priority INTEGER);
CREATE TABLE model_subscription_mapping (id BIGINT PRIMARY KEY, model_id BIGINT, subscription_account_id BIGINT, group_name TEXT, enabled BOOLEAN, upstream_model_id TEXT, priority INTEGER, created_at BIGINT, updated_at BIGINT);
CREATE TABLE model_routings (id BIGINT PRIMARY KEY, group_name TEXT, model VARCHAR(255), subscription_account_id BIGINT, platform TEXT, enabled BOOLEAN, priority INTEGER, created_at BIGINT, updated_at BIGINT);
CREATE TABLE system_options (option_key TEXT, option_value TEXT);
CREATE TABLE subscription_groups (id BIGINT PRIMARY KEY, status INTEGER, daily_limit_usd REAL, weekly_limit_usd REAL, monthly_limit_usd REAL, rate_multiplier REAL);
CREATE TABLE subscription_plans (id BIGINT PRIMARY KEY, group_id BIGINT, for_sale BOOLEAN);
CREATE TABLE user_subscriptions (id BIGINT PRIMARY KEY, user_id BIGINT, group_id BIGINT, status TEXT, starts_at BIGINT, expires_at BIGINT);
CREATE TABLE payment_orders (id BIGINT PRIMARY KEY, user_id TEXT, asset_type TEXT, group_id BIGINT, plan_id BIGINT, subscription_id BIGINT, status TEXT, asset_issue_status TEXT, plan_snapshot TEXT);
